message.content:
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?empCount WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name ;
           sdk:hasNumberOfEmployees ?empCount .
  FILTER(CONTAINS(LCASE(?name), "steel"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?englishName WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?englishName ;
       sdk:hasCertificate ?cert .
  ?cert a sdk:ISO9001 ;
        rdfs:label "ISO 9001" .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naicsText
WHERE {
  ?naics a sdk:NAICS332996.0 ;
         sdk:hasNAICSTextValue ?naicsText ;
         sdk:hasNAICSCodeValue ?code .
  FILTER(?code = 332996)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?code
WHERE {
  ?naicsInst a sdk:NAICS332996.0 ;
              sdk:hasNAICSTextValue ?text ;
              sdk:hasNAICSCodeValue ?code .
  FILTER(CONTAINS(LCASE(?text), "pipe and pipe fitting"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?lat WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city ;
        sdk:hasSpatialCoordinates ?coords .
  ?coords a sdk:TwoDimensionalCartesianSpatialCoordinateDatum ;
          sdk:hasLatitudeValue ?lat .
  ?city rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(?cityLabel), "springfield"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateName WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  FILTER(CONTAINS(LCASE(?cityLabel), "san ")).
  ?state a sdk:State ;
         rdfs:label ?stateName .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?codeValue ?codeText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasPrimaryNAICSClassifier ?naicsClassifier .
  FILTER(CONTAINS(LCASE(?name), "precision"))
  ?naicsClassifier sdk:hasNAICSCodeValue ?codeValue ;
                   sdk:hasNAICSTextValue ?codeText .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?industry ?industryLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              rdfs:label ?name ;
              sdk:suppliesToIndustry ?industry .
  FILTER(CONTAINS(LCASE(?name), "automation"))
  ?industry rdfs:label ?industryLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?name ;
               sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(CONTAINS(LCASE(?name), "tooling"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?cap ?capLabel WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?name .
  FILTER(CONTAINS(LCASE(?name), "aerospace"))
  ?org sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manLabel ?cert ?certLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manLabel .
  FILTER(CONTAINS(LCASE(STR(?manLabel)), "plastics"))
  ?manufacturer sdk:hasCertificate ?cert .
  OPTIONAL { ?cert rdfs:label ?certLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cityLabel WHERE {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:organizationLocatedIn ?site .
  FILTER (str(?name) = "Robotics") .
  ?site sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?name ;
          sdk:organizationLocatedIn ?site .
  FILTER (str(?name) = "Valve")
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?lat ?lon WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?compLabel .
  FILTER(?compLabel = "Surface Finish")
  ?company sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?lon .
}
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?certificateLabel (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              sdk:hasCertificate ?certificate .
  ?certificate a ?certClass .
  FILTER(?certClass IN (sdk:ISO9001, sdk:ISO14001, sdk:ISO27001, sdk:ISO45001, sdk:ISO13485, sdk:ISOQualityCertificate, sdk:ISO50001, sdk:TL9000, sdk:QualityCertificate))
  OPTIONAL { ?certificate rdfs:label ?certificateLabel . }
}
GROUP BY ?certificate ?certificateLabel
ORDER BY ?certificateLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?naics (COUNT(?m) AS ?numManufacturers)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naics .
}
GROUP BY ?naics
ORDER BY ?naics

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?manufacturer (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT (COUNT(DISTINCT ?org) AS ?countWithoutDescription)
WHERE {
  ?org a iof-core:Manufacturer .
  FILTER NOT EXISTS {
    ?org iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               sdk:hasCertificate ?cert .
  ?cert a sdk:ISO9001 .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manuf ?name (BOUND(?naics) AS ?hasPrimaryNAICS)
WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?name .
  FILTER(CONTAINS(LCASE(?name), "pipe"))
  OPTIONAL { ?manuf sdk:hasPrimaryNAICSClassifier ?naics . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manuf ?manufLabel ?prod ?prodLabel
WHERE {
  ?manuf a iof-core:Manufacturer ;
          sdk:manufactures ?prod .
  ?manuf rdfs:label ?manufLabel .
  ?prod a iof-core:MaterialProduct ;
        rdfs:label ?prodLabel .
  FILTER(CONTAINS(LCASE(?prodLabel), "valve"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?site ?lat ?lon
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords a sdk:TwoDimensionalCartesianSpatialCoordinateDatum ;
          sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?lon .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

ASK WHERE {
  ?m rdf:type iof-core:Manufacturer .
  FILTER NOT EXISTS { ?m sdk:hasCertificate ?c . }
}

ASK WHERE {
  ?man a iof-core:Manufacturer ;
       rdfs:label ?manLabel .
  FILTER(CONTAINS(LCASE(?manLabel), "coating"))
  ?man iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription .
  ?desc iof-scro:hasTextValue ?descText .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name ?employeeCount
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasNumberOfEmployees ?employeeCount .
  FILTER ( ?employeeCount > 500 )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manuf ?name
WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?name .
  FILTER(REGEX(?name, "^A"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?naics ?text
WHERE {
  ?naics a sdk:NAICS332996.0 ;
         sdk:hasNAICSTextValue ?text .
  FILTER (CONTAINS(LCASE(?text), "pipe"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue "85027.0"^^xsd:string .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manuf ?manufLabel ?stateLabel
WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?manufLabel ;
          sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER regex(?stateLabel, "^New ")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              rdfs:label ?manLabel ;
              sdk:suppliesToIndustry ?industry .
  {
    ?industry rdfs:label ?industryLabel .
    FILTER(CONTAINS(LCASE(?industryLabel), "utilities"))
  } UNION {
    ?industry a sdk:UtilitiesIndustry .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manuf ?manufLabel ?prod ?prodLabel
WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?manufLabel ;
          sdk:manufactures ?prod .
  ?prod a iof-core:MaterialProduct ;
        rdfs:label ?prodLabel .
}
ORDER BY ?manufLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturerName WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?manufacturerName .
  FILTER (STRLEN(STR(?manufacturerName)) > 8)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              sdk:hasNumberOfEmployees ?employees .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
}
ORDER BY DESC(?employees)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  VALUES ?industry { sdk:industry-001 sdk:industry-002 }
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?certificateLabel ?manufacturerCount
WHERE {
  {
    SELECT ?certificate (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                  sdk:hasCertificate ?certificate .
    }
    GROUP BY ?certificate
  }
  OPTIONAL { ?certificate rdfs:label ?certificateLabel . }
}
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer (COUNT(DISTINCT ?cap) AS ?distinctCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
  ?manufacturer sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city a sdk:City .
}
GROUP BY ?manufacturer
ORDER BY DESC(?distinctCapabilities)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naics ?code ?text (COUNT(?m) AS ?numManufacturers)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?code . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?text . }
}
GROUP BY ?naics ?code ?text
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?naicsText
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    ?naics sdk:hasNAICSTextValue ?naicsText .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer ?zipValue
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:hasZIPcode ?zip .
    ?zip sdk:hasIntegerValue ?zipValue .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?name ;
               sdk:hasProcessCapability ?cap .
  { ?cap a sdk:MachiningCapability . } UNION { ?cap a sdk:CoatingCapability . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (GROUP_CONCAT(DISTINCT ?capName; SEPARATOR=", ") AS ?capNames)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
    ?cap rdfs:label ?capName .
  } UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?cap .
    ?cap rdfs:label ?capName .
  }
}
GROUP BY ?manufacturer
ORDER BY ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cityName ?stateName WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer sdk:organizationLocatedIn ?site . }
  OPTIONAL {
    ?site sdk:locatedInCity ?city .
    ?city rdfs:label ?cityName .
  }
  OPTIONAL {
    ?site sdk:locatedInCity ?city .
    ?city sdk:locatedInState ?state .
    ?state rdfs:label ?stateName .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:suppliesToIndustry ?ind .
  { ?ind a sdk:RenewableEnergyIndustry . } UNION { ?ind a sdk:UtilitiesIndustry . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?itemLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?manufacturerLabel .
  {
    ?manufacturer sdk:manufactures ?item .
    ?item rdfs:label ?itemLabel .
  } UNION {
    ?manufacturer sdk:hasCertificate ?item .
    ?item rdfs:label ?itemLabel .
  }
}
ORDER BY ?manufacturerLabel ?itemLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?manufacturer ?lat ?long
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:hasSpatialCoordinates ?coords .
    ?coords sdk:hasLatitudeValue ?lat .
    ?coords sdk:hasLongitudeValue ?long .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?description
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?descText .
  }
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  BIND (COALESCE(?descText, ?name) AS ?description)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?capLabel ?capType WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
    ?cap rdfs:label ?capLabel .
    BIND("process" AS ?capType)
  }
  UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?cap .
    ?cap rdfs:label ?capLabel .
    BIND("material" AS ?capType)
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?cityLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              rdfs:label ?manufacturerLabel ;
              sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(?cityLabel), LCASE("Rochester")))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               sdk:organizationLocatedIn ?site .
