WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?numDistinctSupplierCompanies)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?label ;
               iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?text .
  FILTER (STRLEN(?text) > 20)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name ?naicsText WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naicsInst .
  ?naicsInst a sdk:NAICS332996.0 ;
             sdk:hasNAICSTextValue ?naicsText .
  ?manufacturer rdfs:label ?name .
  FILTER(CONTAINS(LCASE(?naicsText), "pipe"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?name
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?name ;
       sdk:suppliesToIndustry ?indA , ?indB .
  FILTER(?indA != ?indB)
  FILTER(?indA IN (sdk:industry-001, sdk:industry-002) && ?indB IN (sdk:industry-001, sdk:industry-002))
  FILTER NOT EXISTS { ?org sdk:suppliesToIndustry ?extra .
                      FILTER(?extra NOT IN (?indA, ?indB)) }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?man ?label (COUNT(DISTINCT ?prod) AS ?productCount)
WHERE {
  ?man a iof-core:Manufacturer .
  ?man sdk:manufactures ?prod .
  OPTIONAL { ?man rdfs:label ?label . }
}
GROUP BY ?man ?label
HAVING (COUNT(DISTINCT ?prod) = (
  SELECT MAX(?c) WHERE {
    {
      SELECT (COUNT(DISTINCT ?pp) AS ?c)
      WHERE {
        ?m2 a iof-core:Manufacturer ;
            sdk:manufactures ?pp .
      }
      GROUP BY ?m2
    }
  }
))

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?org) AS ?manufacturerCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?manufacturerCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?companyLabel ?employees WHERE {
  {
    SELECT ?state (MAX(?e) AS ?maxEmployees) WHERE {
      ?c a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?s ;
         sdk:hasNumberOfEmployees ?e .
      ?s sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    } GROUP BY ?state
  }
  ?company a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?emp .
  ?site sdk:locatedInCity ?city2 .
  ?city2 sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  BIND(xsd:integer(?emp) AS ?employees) .
  FILTER(?employees = ?maxEmployees)
  ?company rdfs:label ?companyLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?label (COUNT(DISTINCT ?cap) AS ?total)
WHERE {
  ?org a iof-core:Manufacturer .
  OPTIONAL { ?org rdfs:label ?label . }
  {
    ?org sdk:hasProcessCapability ?cap .
  } UNION {
    ?org sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?org ?label
ORDER BY DESC(?total)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name (COALESCE(?coords, "no-coords") AS ?coords)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coordsDatum .
      ?coordsDatum sdk:hasLatitudeValue ?lat ;
                   sdk:hasLongitudeValue ?lon .
      BIND(CONCAT(STR(?lat), ",", STR(?lon)) AS ?coords)
    }
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer ?value
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:hasZIPcode ?zipCode .
    ?zipCode sdk:hasIntegerValue ?zip .
  }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?sitePostal .
    ?sitePostal sdk:hasPostalAddress ?addr .
    ?addr iof-scro:hasTextValue ?postalText .
  }
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  BIND ( COALESCE(?zip, ?postalText, ?name) AS ?value )
}
ORDER BY ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capLabel; SEPARATOR=", ") AS ?Capabilities)
WHERE {
  ?man a iof-core:Manufacturer ;
       rdfs:label ?manufacturerLabel .
  { ?man sdk:hasProcessCapability ?procCap .
    ?procCap rdfs:label ?capLabel .
  }
  UNION
  { ?man sdk:hasMaterialCapability ?matCap .
    ?matCap rdfs:label ?capLabel .
  }
}
GROUP BY ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }

  {
    ?manufacturer sdk:hasProcessCapability ?procCap .
    ?procCap rdfs:label ?procLabel .
    FILTER regex(?procLabel, "ing$", "i")
  }
  UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?matCap .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufLabel ?site ?city ?cityLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufLabel ;
                sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?mLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?mLabel .
  {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:locatedInCity ?city .
    ?city sdk:locatedInState ?state .
  } UNION {
    ?manufacturer sdk:organizationLocatedIn ?state .
    ?state a sdk:State .
  }
  ?state rdfs:label ?stateLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?name .
  FILTER(NOT EXISTS {
    ?manufacturer sdk:hasProcessCapability ?cap .
    ?cap rdfs:label ?capLabel .
    FILTER(!REGEX(?capLabel, "ing$"))
  })
  ?manufacturer sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasMaterialCapability ?cap .
  {
    ?cap a sdk:BronzeProcessingCapability .
  } UNION {
    ?cap a sdk:StainlessSteelProcessingCapability .
  } UNION {
    ?cap a sdk:UrethaneProcessingCapability .
  }
  FILTER NOT EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?otherCap .
    ?otherCap a ?otherType .
    FILTER(?otherType != sdk:BronzeProcessingCapability && ?otherType != sdk:StainlessSteelProcessingCapability && ?otherType != sdk:UrethaneProcessingCapability)
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufLabel ?site ?lat ?lon
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufLabel . }
  ?site a sdk:GeospatialLocation ;
        sdk:hasSpatialCoordinates ?coords .
  OPTIONAL { ?coords sdk:hasLatitudeValue ?lat . }
  OPTIONAL { ?coords sdk:hasLongitudeValue ?lon . }
  FILTER (!BOUND(?lat) || !BOUND(?lon))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer sdk:hasCertificate ?cert .
  FILTER NOT EXISTS { ?manufacturer sdk:manufactures ?prod . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?text .
  }
  FILTER ( !BOUND(?desc) || !BOUND(?text) || STR(?text) = "" || REGEX(STR(?text), "^[\\s]*$") )
  OPTIONAL { ?manufacturer rdfs:label ?name . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER NOT EXISTS { ?manufacturer sdk:suppliesToIndustry ?ind . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?orgLabel (COUNT(?cert) AS ?certCount)
WHERE {
  ?org a iof-core:Manufacturer .
  OPTIONAL { ?org sdk:hasCertificate ?cert . }
  ?org rdfs:label ?orgLabel .
}
GROUP BY ?org ?orgLabel
HAVING (COUNT(?cert) > (
  SELECT (AVG(?cc) AS ?avgCerts) WHERE {
    SELECT ?m (COUNT(?c) AS ?cc) WHERE {
      ?m a iof-core:Manufacturer .
      OPTIONAL { ?m sdk:hasCertificate ?c . }
    } GROUP BY ?m
  }
))

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?emp ?avgEmp
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               sdk:hasNumberOfEmployees ?emp ;
               sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }

  {
    SELECT ?industry (AVG(?emp) AS ?avgEmp)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:hasNumberOfEmployees ?emp ;
         sdk:suppliesToIndustry ?industry .
    }
    GROUP BY ?industry
  }

  FILTER(xsd:decimal(?emp) > ?avgEmp)
}
ORDER BY ?industry ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel (AVG(?employees) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?stateLabel ?mfr ?employees
    WHERE {
      ?mfr a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?employees ;
           sdk:manufactures ?prod .
      ?site sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      ?prod rdfs:label ?prodLabel .
      FILTER regex(?prodLabel, "[0-9]") .
    }
  }
}
GROUP BY ?stateLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsCodeValue
       (COUNT(DISTINCT ?man) AS ?manufacturerCount)
       (COUNT(DISTINCT ?prod) AS ?productCount)
       (AVG(?emp) AS ?avgEmployees)
WHERE {
  ?man a iof-core:Manufacturer ;
       sdk:hasPrimaryNAICSClassifier ?naicsNode ;
       sdk:hasNumberOfEmployees ?emp ;
       sdk:manufactures ?prod .
  ?naicsNode a sdk:NAICS332996.0 ;
             sdk:hasNAICSCodeValue ?naicsCodeValue .
}
GROUP BY ?naicsCodeValue

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?companyName WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?companyName .
  FILTER ( LANG(?companyName) = "en" || LANG(?companyName) = "" )
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(?productLabel = "Tube Bending" || ?productLabel = "Punching")
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cityLabel (AVG(?emp) AS ?avgEmployee)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site ;
     sdk:hasNumberOfEmployees ?emp .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER EXISTS {
    SELECT ?m (COUNT(DISTINCT ?cap) AS ?capCount) WHERE {
      { ?m sdk:hasProcessCapability ?cap . } UNION { ?m sdk:hasMaterialCapability ?cap . }
    } GROUP BY ?m
    HAVING (COUNT(DISTINCT ?cap) >= 4)
  }
}
GROUP BY ?cityLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
       (COUNT(DISTINCT ?prod) AS ?prodCount)
       (COUNT(DISTINCT ?proc) AS ?procCount)
       (COUNT(DISTINCT ?mat) AS ?matCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL { ?manufacturer sdk:manufactures ?prod . }
  OPTIONAL { ?manufacturer sdk:hasProcessCapability ?proc . }
  OPTIONAL { ?manufacturer sdk:hasMaterialCapability ?mat . }
}
GROUP BY ?manufacturer ?label
HAVING ((COUNT(DISTINCT ?prod) = 2) || ((COUNT(DISTINCT ?proc) = 2) && (COUNT(DISTINCT ?mat) = 2)))
